(* [comment removed for export] *)
Definition bytes_at (m : word -> option byte) (a : Z) (bs : list byte) : Prop :=
  (0 <= a)%Z /\ (a + Z.of_nat (length bs) <= 2^64)%Z /\
  forall i, (i < length bs)%nat -> mrd m (wa (a + Z.of_nat i)) = nth_error bs i.

(* [comment removed for export] *)
Definition wr_at (m : word -> option byte) (a : Z) (n : Z) : Prop :=
  (0 <= a)%Z /\ (a + n <= 2^64)%Z /\
  forall i, (0 <= i < n)%Z -> wview segs m (wa (a + i)) <> None.

(* [comment removed for export] *)
Definition ro_addr (a : word) : bool :=
  match find_segment segs (bv_unsigned a) 1 with
  | Some seg => negb (seg_writable seg)
  | None => false
  end.

(* [comment removed for export] *)
Definition seg_addr (a : word) : bool :=
  match find_segment segs (bv_unsigned a) 1 with
  | Some _ => true
  | None => false
  end.

(* [comment removed for export] *)
Definition UTOP : Z := 0x800000000000%Z.

(* [comment removed for export] *)
Definition mem_ok_at (m : word -> option byte) (a : word) : bool :=
  (if seg_addr a then Z.ltb (bv_unsigned a) UTOP else true) &&
  match m a with
  | Some _ => negb (ro_addr a) && Z.ltb (bv_unsigned a) UTOP
  | None => true
  end.
Definition mem_inv (m : word -> option byte) : Prop := forall a : word, mem_ok_at m a = true.
