(* [comment removed for export] *)
Lemma bytes_at_write_other : forall m a bs c cs,
  bytes_at m c cs ->
  (0 <= a)%Z -> (a + Z.of_nat (length bs) <= 2^64)%Z ->
  (c + Z.of_nat (length cs) <= a \/ a + Z.of_nat (length bs) <= c)%Z ->
  bytes_at (write_to_mem m (wa a) bs) c cs.
Proof.
