Lemma upd_bytes_nth : forall cs k bs i, (k + length bs <= length cs)%nat -> (i < length cs)%nat ->
  nth_error (upd_bytes cs k bs) i =
    if (Nat.leb k i && Nat.ltb i (k + length bs))%bool then nth_error bs (i - k) else nth_error cs i.
Proof.
