Definition sx8 (v : word) : word := Z_to_bv 64 (bv_swrap 8 (bv_unsigned v)).
Definition zxb (b : byte) : word := Z_to_bv 64 (bv_unsigned b).
Definition sxb (b : byte) : word := Z_to_bv 64 (bv_signed b).

